/*!
 * AdventureWorks · Internet Sales Analytics
 * Static, dependency-free dashboard over dashboard/data.js (window.AW).
 * Generated by build/prepare_data.py from the read-only AdventureWorksDW.xlsx.
 */
(function () {
  'use strict';

  const AW = window.AW;
  const boot = document.getElementById('boot');
  if (!AW || !AW.fact || !AW.fact.length) {
    if (boot) boot.textContent = 'data.js did not load';
    return;
  }

  /* ------------------------------------------------------------------ data */

  const fact = AW.fact;
  const products = AW.products;
  const customers = AW.customers;
  const geos = AW.geos;
  const territories = AW.territories;
  const months = AW.months;
  const dates = AW.dates;
  const meta = AW.meta;
  const N = fact.length;

  const PALETTE = ['#0f766e', '#c9a227', '#c96a4b', '#1b3550', '#2f7d5b', '#8c7016', '#5b7c99', '#a4432a', '#15968b', '#9aa4ad'];

  const INCOME_BANDS = [
    { key: 'u40', label: 'Under $40K', lo: 0, hi: 40000 },
    { key: '40_70', label: '$40K – $70K', lo: 40000, hi: 70000 },
    { key: '70_100', label: '$70K – $100K', lo: 70000, hi: 100000 },
    { key: '100p', label: '$100K+', lo: 100000, hi: Infinity }
  ];

  function bandKey(income) {
    for (let i = 0; i < INCOME_BANDS.length; i++) {
      const b = INCOME_BANDS[i];
      if (income >= b.lo && income < b.hi) return b.key;
    }
    return INCOME_BANDS[0].key;
  }
  function bandLabel(key) {
    const b = INCOME_BANDS.find(function (x) { return x.key === key; });
    return b ? b.label : key;
  }

  const CUST_COUNTRY = customers.map(function (c) {
    const g = geos[c.geo];
    return g && g.country ? g.country : 'Unknown';
  });
  const CUST_BAND = customers.map(function (c) { return bandKey(c.income); });
  const PROD_LINE = products.map(function (p) { return p.line || 'Unspecified'; });

  /* date index -> month / year */
  const monthOf = new Int16Array(dates.length);
  const yearOf = new Int16Array(dates.length);
  months.forEach(function (m, i) {
    for (let d = m.start; d <= m.end && d < monthOf.length; d++) monthOf[d] = i;
  });
  dates.forEach(function (d, i) { yearOf[i] = Number(d.slice(0, 4)); });

  /* lifetime spend per customer (full data, independent of filters) */
  const lifetime = new Float64Array(customers.length);
  for (let i = 0; i < N; i++) lifetime[fact[i][2]] += fact[i][8];
  const spenders = Array.prototype.slice.call(lifetime).filter(function (v) { return v > 0; }).sort(function (a, b) { return a - b; });
  function quant(p) {
    if (!spenders.length) return 0;
    return spenders[Math.min(spenders.length - 1, Math.max(0, Math.round(p * (spenders.length - 1))))];
  }
  const Q1 = quant(0.25), Q2 = quant(0.5), Q3 = quant(0.75);
  const VBANDS = [
    { key: 'top', label: 'Top 25%', test: function (v) { return v > Q3; } },
    { key: 'upper', label: 'Upper mid 25%', test: function (v) { return v > Q2 && v <= Q3; } },
    { key: 'lower', label: 'Lower mid 25%', test: function (v) { return v > Q1 && v <= Q2; } },
    { key: 'bottom', label: 'Bottom 25%', test: function (v) { return v <= Q1; } }
  ];
  const CUST_VBAND = new Array(customers.length);
  for (let i = 0; i < customers.length; i++) {
    const v = lifetime[i];
    for (let b = 0; b < VBANDS.length; b++) {
      if (VBANDS[b].test(v)) { CUST_VBAND[i] = VBANDS[b].key; break; }
    }
  }

  /* -------------------------------------------------------------- formatting */

  const nf0 = new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 });
  const nf2 = new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function money(v) {
    if (!isFinite(v)) return '—';
    const a = Math.abs(v);
    if (a >= 1e9) return '$' + (v / 1e9).toFixed(2) + 'B';
    if (a >= 1e6) return '$' + (v / 1e6).toFixed(2) + 'M';
    if (a >= 1e3) return '$' + (v / 1e3).toFixed(1) + 'K';
    return '$' + nf0.format(Math.round(v));
  }
  function moneyFull(v) { return isFinite(v) ? '$' + nf2.format(v) : '—'; }
  function moneyAxis(v) {
    const a = Math.abs(v);
    if (a >= 1e6) return '$' + (v / 1e6).toFixed(a >= 1e7 ? 0 : 1) + 'M';
    if (a >= 1e3) return '$' + Math.round(v / 1e3) + 'K';
    return '$' + Math.round(v);
  }
  function pct(v) { return isFinite(v) ? (v * 100).toFixed(2) + '%' : '—'; }
  function pct1(v) { return isFinite(v) ? (v * 100).toFixed(1) + '%' : '—'; }
  function int(v) { return isFinite(v) ? nf0.format(Math.round(v)) : '—'; }
  function dec(v) { return isFinite(v) ? v.toFixed(2) : '—'; }

  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function truncate(s, max) {
    s = String(s);
    if (max < 3) max = 3;
    return s.length <= max ? s : s.slice(0, max - 1) + '…';
  }
  function csvCell(v) {
    const s = v == null ? '' : String(v);
    return /[",\r\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
  }

  /* ----------------------------------------------------------------- tooltip */

  const tipEl = document.getElementById('tooltip');
  function showTip(evt, title, rows) {
    if (!tipEl) return;
    tipEl.innerHTML = '<div class="tip-title">' + esc(title) + '</div>' + rows.map(function (r) {
      return '<div class="tip-row"><span>' + esc(r[0]) + '</span><b>' + esc(r[1]) + '</b></div>';
    }).join('');
    tipEl.classList.add('show');
    const pad = 16;
    const box = tipEl.getBoundingClientRect();
    let x = evt.clientX + pad;
    let y = evt.clientY + pad;
    if (x + box.width > window.innerWidth - 8) x = evt.clientX - box.width - pad;
    if (y + box.height > window.innerHeight - 8) y = evt.clientY - box.height - pad;
    tipEl.style.left = Math.max(8, x) + 'px';
    tipEl.style.top = Math.max(8, y) + 'px';
  }
  function hideTip() { if (tipEl) tipEl.classList.remove('show'); }

  /* --------------------------------------------------------------------- svg */

  const NS = 'http://www.w3.org/2000/svg';
  function svgEl(tag, attrs) {
    const e = document.createElementNS(NS, tag);
    if (attrs) Object.keys(attrs).forEach(function (k) { e.setAttribute(k, attrs[k]); });
    return e;
  }
  function svgText(x, y, str, attrs) {
    const a = { x: x, y: y, 'font-size': 10, fill: '#7b8792', 'font-family': 'Segoe UI, system-ui, sans-serif' };
    if (attrs) Object.keys(attrs).forEach(function (k) { a[k] = attrs[k]; });
    const t = svgEl('text', a);
    t.textContent = str;
    return t;
  }
  function emptyChart(msg) {
    return '<div class="empty-chart">' + esc(msg || 'No rows match the current selection.') + '</div>';
  }

  function drawArea(host, spec) {
    host.innerHTML = '';
    const rows = spec.rows || [];
    const vals = rows.map(function (r) { return r.value; });
    const max = Math.max.apply(null, vals.concat([0]));
    const min = spec.yMin != null ? spec.yMin : Math.min.apply(null, vals.concat([0]));
    if (!rows.length || !(max > min)) { host.innerHTML = emptyChart(spec.empty); return; }

    const W = Math.max(260, host.clientWidth || 640);
    const H = Math.max(150, host.clientHeight || 280);
    const pad = { l: 58, r: 16, t: 14, b: 26 };
    const iw = W - pad.l - pad.r;
    const ih = H - pad.t - pad.b;
    const yMax = spec.yMax != null ? spec.yMax : max * 1.12;
    const yMin = spec.yMin != null ? spec.yMin : min;
    const n = rows.length;
    const X = function (i) { return pad.l + (n === 1 ? iw / 2 : (i / (n - 1)) * iw); };
    const Y = function (v) { return pad.t + ih - ((v - yMin) / (yMax - yMin)) * ih; };
    const color = spec.color || '#0f766e';
    const svg = svgEl('svg', { width: W, height: H, viewBox: '0 0 ' + W + ' ' + H, role: 'img' });

    const gid = 'grad-' + Math.random().toString(36).slice(2, 9);
    const defs = svgEl('defs');
    const lg = svgEl('linearGradient', { id: gid, x1: 0, y1: 0, x2: 0, y2: 1 });
    lg.appendChild(svgEl('stop', { offset: '0%', 'stop-color': color, 'stop-opacity': 0.26 }));
    lg.appendChild(svgEl('stop', { offset: '100%', 'stop-color': color, 'stop-opacity': 0.02 }));
    defs.appendChild(lg);
    svg.appendChild(defs);

    [0, 0.25, 0.5, 0.75, 1].forEach(function (t) {
      const v = yMin + (yMax - yMin) * (1 - t);
      const y = pad.t + ih * t;
      svg.appendChild(svgEl('line', { x1: pad.l, y1: y, x2: W - pad.r, y2: y, stroke: '#ece7dc', 'stroke-width': 1 }));
      svg.appendChild(svgText(pad.l - 8, y + 3.5, (spec.axis || moneyAxis)(v), { 'text-anchor': 'end', 'font-size': 9.5 }));
    });

    const line = rows.map(function (r, i) { return (i ? 'L' : 'M') + X(i).toFixed(2) + ',' + Y(r.value).toFixed(2); }).join(' ');
    const area = line + ' L' + X(n - 1).toFixed(2) + ',' + (pad.t + ih).toFixed(2) + ' L' + X(0).toFixed(2) + ',' + (pad.t + ih).toFixed(2) + ' Z';
    svg.appendChild(svgEl('path', { d: area, fill: 'url(#' + gid + ')' }));
    svg.appendChild(svgEl('path', { d: line, fill: 'none', stroke: color, 'stroke-width': 2, 'stroke-linejoin': 'round', 'stroke-linecap': 'round' }));

    if (spec.ref != null && spec.ref > yMin && spec.ref < yMax) {
      const ry = Y(spec.ref);
      svg.appendChild(svgEl('line', { x1: pad.l, y1: ry, x2: W - pad.r, y2: ry, stroke: '#c9a227', 'stroke-width': 1.2, 'stroke-dasharray': '4 4' }));
      svg.appendChild(svgText(W - pad.r, ry - 4, spec.refLabel || '', { 'text-anchor': 'end', 'font-size': 9, fill: '#8c7016' }));
    }

    const every = spec.labelEvery || Math.max(1, Math.ceil(n / 8));
    rows.forEach(function (r, i) {
      if (i % every !== 0 && i !== n - 1) return;
      svg.appendChild(svgText(X(i), H - 8, r.label, { 'text-anchor': 'middle', 'font-size': 9 }));
    });

    const cross = svgEl('line', { x1: 0, y1: pad.t, x2: 0, y2: pad.t + ih, stroke: '#c9a227', 'stroke-width': 1, 'stroke-dasharray': '3 3', opacity: 0 });
    const dot = svgEl('circle', { cx: 0, cy: 0, r: 4, fill: '#fff', stroke: color, 'stroke-width': 2, opacity: 0 });
    svg.appendChild(cross);
    svg.appendChild(dot);

    const hit = svgEl('rect', { x: pad.l, y: pad.t, width: iw, height: ih, fill: 'transparent' });
    if (spec.onClick) hit.setAttribute('style', 'cursor:pointer');

    function idxAt(clientX) {
      const box = svg.getBoundingClientRect();
      const mx = (clientX - box.left) * (W / (box.width || W));
      if (n === 1) return 0;
      const i = Math.round(((mx - pad.l) / iw) * (n - 1));
      return Math.max(0, Math.min(n - 1, i));
    }

    hit.addEventListener('mousemove', function (ev) {
      const i = idxAt(ev.clientX);
      const r = rows[i];
      cross.setAttribute('x1', X(i)); cross.setAttribute('x2', X(i));
      dot.setAttribute('cx', X(i)); dot.setAttribute('cy', Y(r.value));
      cross.setAttribute('opacity', 1); dot.setAttribute('opacity', 1);
      showTip(ev, r.label, spec.tip ? spec.tip(r) : [['Value', money(r.value)]]);
    });
    hit.addEventListener('mouseleave', function () {
      cross.setAttribute('opacity', 0); dot.setAttribute('opacity', 0); hideTip();
    });
    if (spec.onClick) {
      hit.addEventListener('click', function (ev) { spec.onClick(rows[idxAt(ev.clientX)]); });
    }
    svg.appendChild(hit);
    host.appendChild(svg);
  }

  function drawBars(host, spec) {
    host.innerHTML = '';
    const rows = (spec.rows || []).filter(function (r) { return isFinite(r.value) && r.value > 0; });
    if (!rows.length) { host.innerHTML = emptyChart(spec.empty); return; }

    const W = Math.max(240, host.clientWidth || 620);
    const H = Math.max(120, host.clientHeight || 280);
    const max = Math.max.apply(null, rows.map(function (r) { return r.value; }));
    const n = rows.length;
    const rowH = Math.min(42, H / n);
    const top = Math.max(0, (H - n * rowH) / 2);
    const labelW = Math.min(Math.max(W * 0.36, 86), 190);
    const valW = 76;
    const x0 = labelW + 10;
    const x1 = W - valW;
    const svg = svgEl('svg', { width: W, height: H, viewBox: '0 0 ' + W + ' ' + H, role: 'img' });

    rows.forEach(function (r, i) {
      const cy = top + rowH * i + rowH / 2;
      const bw = Math.max(2, (r.value / max) * (x1 - x0));
      const color = r.color || spec.color || PALETTE[i % PALETTE.length];
      svg.appendChild(svgText(0, cy + 3.5, truncate(r.label, Math.floor(labelW / 6)), { 'font-size': 10.5, fill: '#40515f' }));
      svg.appendChild(svgEl('rect', { x: x0, y: cy - 4.5, width: Math.max(1, x1 - x0), height: 9, rx: 4.5, fill: '#efeae0' }));
      svg.appendChild(svgEl('rect', { x: x0, y: cy - 4.5, width: bw, height: 9, rx: 4.5, fill: color }));
      svg.appendChild(svgText(W, cy + 3.5, (spec.fmt || money)(r.value), { 'text-anchor': 'end', 'font-size': 10.5, fill: '#12263a', 'font-weight': 600 }));

      const hit = svgEl('rect', { x: 0, y: top + rowH * i, width: W, height: rowH, fill: 'transparent' });
      if (spec.onClick) hit.setAttribute('style', 'cursor:pointer');
      hit.addEventListener('mousemove', function (ev) {
        showTip(ev, r.label, spec.tip ? spec.tip(r) : [['Value', money(r.value)]]);
      });
      hit.addEventListener('mouseleave', hideTip);
      if (spec.onClick) hit.addEventListener('click', function () { spec.onClick(r.key, r); });
      svg.appendChild(hit);
    });
    host.appendChild(svg);
  }

  function drawDonut(host, spec) {
    host.innerHTML = '';
    const rows = (spec.rows || []).filter(function (r) { return r.value > 0; });
    if (!rows.length) { host.innerHTML = emptyChart(spec.empty); return; }

    const W = Math.max(200, host.clientWidth || 320);
    const H = Math.max(150, host.clientHeight || 280);
    const cx = W / 2, cy = H / 2;
    const R = Math.min(W, H) / 2 - 8;
    const IR = R * 0.62;
    const total = rows.reduce(function (s, r) { return s + r.value; }, 0);
    const svg = svgEl('svg', { width: W, height: H, viewBox: '0 0 ' + W + ' ' + H, role: 'img' });

    if (rows.length === 1) {
      const only = rows[0];
      const ring = svgEl('circle', { cx: cx, cy: cy, r: (R + IR) / 2, fill: 'none', stroke: only.color || PALETTE[0], 'stroke-width': R - IR });
      if (spec.onClick) { ring.setAttribute('style', 'cursor:pointer'); ring.addEventListener('click', function () { spec.onClick(only.key, only); }); }
      svg.appendChild(ring);
    } else {
      let a0 = -Math.PI / 2;
      rows.forEach(function (r, i) {
        const a1 = a0 + (r.value / total) * Math.PI * 2;
        const large = a1 - a0 > Math.PI ? 1 : 0;
        function pt(rad, a) { return [cx + rad * Math.cos(a), cy + rad * Math.sin(a)]; }
        const p0 = pt(R, a0), p1 = pt(R, a1), p2 = pt(IR, a1), p3 = pt(IR, a0);
        const d = 'M' + p0[0].toFixed(2) + ',' + p0[1].toFixed(2) +
          ' A' + R.toFixed(2) + ',' + R.toFixed(2) + ' 0 ' + large + ' 1 ' + p1[0].toFixed(2) + ',' + p1[1].toFixed(2) +
          ' L' + p2[0].toFixed(2) + ',' + p2[1].toFixed(2) +
          ' A' + IR.toFixed(2) + ',' + IR.toFixed(2) + ' 0 ' + large + ' 0 ' + p3[0].toFixed(2) + ',' + p3[1].toFixed(2) + ' Z';
        const path = svgEl('path', { d: d, fill: r.color || PALETTE[i % PALETTE.length], stroke: '#fff', 'stroke-width': 1.5 });
        if (spec.onClick) path.setAttribute('style', 'cursor:pointer');
        path.addEventListener('mousemove', function (ev) {
          showTip(ev, r.label, spec.tip ? spec.tip(r) : [['Value', money(r.value)], ['Share', pct(r.value / total)]]);
        });
        path.addEventListener('mouseleave', hideTip);
        if (spec.onClick) path.addEventListener('click', function () { spec.onClick(r.key, r); });
        svg.appendChild(path);
        a0 = a1;
      });
    }

    svg.appendChild(svgText(cx, cy - 1, spec.center != null ? spec.center : money(total), { 'text-anchor': 'middle', 'font-size': 17, 'font-weight': 700, fill: '#12263a', 'font-family': 'Georgia, serif' }));
    svg.appendChild(svgText(cx, cy + 15, spec.centerLabel || 'Total', { 'text-anchor': 'middle', 'font-size': 9, fill: '#7b8792' }));
    host.appendChild(svg);
  }

  /* ---------------------------------------------------------------- state */

  const state = {
    page: 'overview',
    from: 0,
    to: dates.length - 1,
    countries: new Set(),
    lines: new Set(),
    genders: new Set(),
    bands: new Set(),
    cross: null,
    sort: { key: 'date', dir: -1 },
    pageIdx: 0,
    pageSize: 25,
    review: ''
  };

  function genderLabel(g) { return g === 'M' ? 'Male' : g === 'F' ? 'Female' : g; }

  function baseRows() {
    const out = [];
    const from = state.from, to = state.to;
    const cl = state.countries, ln = state.lines, gd = state.genders, bd = state.bands;
    const anyC = cl.size > 0, anyL = ln.size > 0, anyG = gd.size > 0, anyB = bd.size > 0;
    for (let i = 0; i < N; i++) {
      const r = fact[i];
      if (r[0] < from || r[0] > to) continue;
      if (anyL && !ln.has(PROD_LINE[r[1]])) continue;
      if (anyC && !cl.has(CUST_COUNTRY[r[2]])) continue;
      if (anyG && !gd.has(customers[r[2]].gender)) continue;
      if (anyB && !bd.has(CUST_BAND[r[2]])) continue;
      out.push(r);
    }
    return out;
  }

  function crossOk(r, c) {
    switch (c.kind) {
      case 'month': { const m = months[c.i]; return m ? r[0] >= m.start && r[0] <= m.end : true; }
      case 'line': return PROD_LINE[r[1]] === c.value;
      case 'tgroup': return territories[r[3]].group === c.value;
      case 'territory': return String(territories[r[3]].k) === String(c.value);
      case 'country': return CUST_COUNTRY[r[2]] === c.value;
      case 'band': return CUST_BAND[r[2]] === c.value;
      case 'vband': return CUST_VBAND[r[2]] === c.value;
      case 'gender': return customers[r[2]].gender === c.value;
      case 'product': return String(r[1]) === String(c.value);
      case 'customer': return String(r[2]) === String(c.value);
      default: return true;
    }
  }

  function currentRows() {
    const base = baseRows();
    if (!state.cross) return base;
    const c = state.cross;
    return base.filter(function (r) { return crossOk(r, c); });
  }

  function setCross(kind, value, label) {
    const c = state.cross;
    if (c && c.kind === kind && String(c.value) === String(value)) state.cross = null;
    else state.cross = { kind: kind, value: String(value), label: label };
    state.pageIdx = 0;
    render();
  }

  function clearCross() { state.cross = null; state.pageIdx = 0; render(); }

  /* ----------------------------------------------------------- aggregation */

  function agg(list) {
    let rev = 0, profit = 0, units = 0, freight = 0;
    const orders = new Set(), custs = new Set();
    for (let i = 0; i < list.length; i++) {
      const r = list[i];
      rev += r[8]; profit += r[9]; units += r[5]; freight += r[10];
      orders.add(r[4]); custs.add(r[2]);
    }
    return {
      rev: rev, profit: profit, units: units, freight: freight,
      orders: orders.size, customers: custs.size, lines: list.length,
      margin: rev ? profit / rev : 0,
      aov: orders.size ? rev / orders.size : 0
    };
  }

  function groupBy(list, keyFn, labelFn) {
    const map = new Map();
    for (let i = 0; i < list.length; i++) {
      const r = list[i];
      const k = keyFn(r);
      let g = map.get(k);
      if (!g) {
        g = { key: k, label: labelFn ? labelFn(k) : String(k), rev: 0, profit: 0, units: 0, freight: 0, lines: 0, orders: new Set(), custs: new Set() };
        map.set(k, g);
      }
      g.rev += r[8]; g.profit += r[9]; g.units += r[5]; g.freight += r[10]; g.lines++;
      g.orders.add(r[4]); g.custs.add(r[2]);
    }
    const out = [];
    map.forEach(function (g) {
      out.push({
        key: g.key, label: g.label, rev: g.rev, profit: g.profit, units: g.units, freight: g.freight,
        lines: g.lines, orders: g.orders.size, customers: g.custs.size,
        margin: g.rev ? g.profit / g.rev : 0
      });
    });
    return out;
  }

  function repeatStats(list) {
    const m = new Map();
    for (let i = 0; i < list.length; i++) {
      const r = list[i];
      let s = m.get(r[2]);
      if (!s) { s = new Set(); m.set(r[2], s); }
      s.add(r[4]);
    }
    let rep = 0;
    m.forEach(function (s) { if (s.size >= 2) rep++; });
    return { customers: m.size, repeat: rep, rate: m.size ? rep / m.size : 0 };
  }

  /* ---------------------------------------------------------- ui fragments */

  function pageHead(num, kicker, title, lede, side) {
    return '<div class="page-head"><div>' +
      '<div class="eyebrow"><span class="eyebrow-num">' + num + '</span>' + esc(kicker) + '</div>' +
      '<h1>' + esc(title) + '</h1>' +
      '<p class="lede">' + lede + '</p>' +
      '</div><div class="page-side">' + side + '</div></div>';
  }

  function kpis(items) {
    return '<div class="kpi-grid">' + items.map(function (k, i) {
      const primary = i === 0;
      const tone = !primary && k.tone ? ' data-tone="' + k.tone + '"' : '';
      return '<div class="kpi' + (primary ? ' primary' : '') + '"' + tone + '>' +
        '<div class="kpi-label">' + esc(k.label) + '</div>' +
        '<div class="kpi-value">' + esc(k.value) + '</div>' +
        '<div class="kpi-sub">' + k.sub + '</div>' +
        '</div>';
    }).join('') + '</div>';
  }

  function card(opts) {
    return '<section class="card ' + (opts.span || 'span-6') + '">' +
      '<div class="card-head"><div>' +
      (opts.kicker ? '<div class="card-kicker">' + esc(opts.kicker) + '</div>' : '') +
      '<h2>' + esc(opts.title) + '</h2>' +
      (opts.sub ? '<p class="card-sub">' + opts.sub + '</p>' : '') +
      '</div>' + (opts.actions ? '<div class="card-actions">' + opts.actions + '</div>' : '') +
      '</div>' + opts.body + '</section>';
  }

  function table(headers, body, foot) {
    const th = headers.map(function (h) {
      const o = typeof h === 'string' ? { label: h } : h;
      return '<th' + (o.cls ? ' class="' + o.cls + '"' : '') + '>' + (o.html || esc(o.label)) + '</th>';
    }).join('');
    return '<div class="table-wrap"><table class="data"><thead><tr>' + th + '</tr></thead>' +
      '<tbody>' + body + '</tbody>' +
      (foot ? '<tfoot><tr>' + foot + '</tr></tfoot>' : '') +
      '</table></div>';
  }

  function legendHTML(items, fmt) {
    return '<div class="legend">' + items.map(function (it) {
      return '<span class="legend-item"><span class="legend-swatch round" style="background:' + (it.color || '#0f766e') + '"></span>' +
        esc(it.label) + ' <b>' + fmt(it) + '</b></span>';
    }).join('') + '</div>';
  }

  function insight(text) {
    return '<div class="insight"><div class="insight-mark">“</div><div>' +
      '<div class="insight-label">What the data says</div><p>' + text + '</p></div></div>';
  }

  function crossbar() {
    const c = state.cross;
    if (!c) return '';
    return '<div class="crossbar"><button type="button" data-action="clear-cross">' +
      esc(c.label) + ' <b>× clear</b></button></div>';
  }

  let chartQueue = [];
  let chartSeq = 0;
  function chartSlot(kind, spec, cls) {
    const id = 'chart-' + (++chartSeq);
    chartQueue.push({ id: id, kind: kind, spec: spec });
    return '<div class="chart' + (cls ? ' ' + cls : '') + '" id="' + id + '"></div>';
  }
  function flushCharts() {
    const q = chartQueue;
    chartQueue = [];
    q.forEach(function (item) {
      const host = document.getElementById(item.id);
      if (!host) return;
      try {
        if (item.kind === 'area') drawArea(host, item.spec);
        else if (item.kind === 'bars') drawBars(host, item.spec);
        else if (item.kind === 'donut') drawDonut(host, item.spec);
      } catch (err) {
        console.error(err);
        host.innerHTML = emptyChart('This chart could not be drawn.');
      }
    });
  }

  /* -------------------------------------------------------------- overview */

  function pageOverview() {
    const R = currentRows();
    const a = agg(R);
    const mRev = new Float64Array(months.length);
    const mProfit = new Float64Array(months.length);
    for (let i = 0; i < R.length; i++) {
      const r = R[i];
      const mi = monthOf[r[0]];
      mRev[mi] += r[8];
      mProfit[mi] += r[9];
    }
    const trend = months.map(function (m, i) {
      return { key: m.key, label: m.short, value: mRev[i], profit: mProfit[i], i: i };
    });

    const tgroups = groupBy(R, function (r) { return territories[r[3]].group; }).sort(function (x, y) { return y.rev - x.rev; });
    const lines = groupBy(R, function (r) { return PROD_LINE[r[1]]; }).sort(function (x, y) { return y.rev - x.rev; });
    const countries = groupBy(R, function (r) { return CUST_COUNTRY[r[2]]; }).sort(function (x, y) { return y.rev - x.rev; });

    const tgRows = tgroups.map(function (g, i) {
      return { key: g.key, label: g.label, value: g.rev, color: PALETTE[i % PALETTE.length], g: g };
    });
    const lineRows = lines.map(function (g, i) {
      return { key: g.key, label: g.label, value: g.rev, color: PALETTE[i % PALETTE.length], g: g };
    });
    const countryRows = countries.slice(0, 8).map(function (g) {
      return { key: g.key, label: g.label, value: g.rev, g: g };
    });

    let body = '';
    let prev = null;
    months.forEach(function (m, i) {
      if (!mRev[i] && !mProfit[i]) { prev = 0; return; }
      const mom = prev && prev > 0 ? (mRev[i] - prev) / prev : null;
      body += '<tr class="clickable" data-action="month" data-value="' + i + '" data-label="' + esc(m.label) + '">' +
        '<td>' + esc(m.label) + '</td>' +
        '<td class="num">' + money(mRev[i]) + '</td>' +
        '<td class="num">' + money(mProfit[i]) + '</td>' +
        '<td class="num">' + pct(mRev[i] ? mProfit[i] / mRev[i] : 0) + '</td>' +
        '<td class="num">' + (mom == null ? '—' : (mom >= 0 ? '+' : '') + pct(mom)) + '</td></tr>';
      prev = mRev[i];
    });

    return pageHead('01', 'Portfolio performance', 'Overview',
      'Two years of internet sales on the re-based calendar: what sold, where it shipped and how much margin it carried.',
      '<strong>' + esc(dates[0]) + ' → ' + esc(dates[dates.length - 1]) + '</strong>' +
      int(a.lines) + ' lines · ' + int(a.orders) + ' orders<br>' + int(a.customers) + ' customers in selection') +
      crossbar() +
      kpis([
        { label: 'Revenue', value: money(a.rev), sub: int(a.units) + ' units · ' + int(a.orders) + ' orders' },
        { label: 'Gross profit', value: money(a.profit), sub: 'Margin ' + pct(a.margin), tone: 'teal' },
        { label: 'Gross margin', value: pct(a.margin), sub: 'Profit ÷ revenue, per-unit × quantity', tone: 'gold' },
        { label: 'Orders', value: int(a.orders), sub: 'AOV ' + money(a.aov), tone: 'green' }
      ]) +
      '<div class="grid">' +
      card({
        span: 'span-8', kicker: 'Trend', title: 'Revenue by month',
        sub: 'Click a month to filter every visual on the page.',
        body: chartSlot('area', {
          rows: trend,
          labelEvery: 3,
          tip: function (r) {
            return [['Revenue', money(r.value)], ['Gross profit', money(r.profit)], ['Margin', pct(r.value ? r.profit / r.value : 0)]];
          },
          onClick: function (r) {
            const c = state.cross;
            if (c && c.kind === 'month' && c.i === r.i) state.cross = null;
            else state.cross = { kind: 'month', value: r.key, label: 'Month: ' + months[r.i].label, i: r.i };
            state.pageIdx = 0;
            render();
          }
        }, 'tall')
      }) +
      card({
        span: 'span-4', kicker: 'Mix', title: 'Revenue by territory group',
        sub: 'Sales territory key on the fact row — ' + int(tgroups.length) + ' groups in view.',
        body: chartSlot('donut', {
          rows: tgRows,
          center: money(a.rev),
          centerLabel: 'Revenue',
          tip: function (r) { return [['Revenue', money(r.value)], ['Share', pct(r.value / (a.rev || 1))], ['Margin', pct(r.g.margin)]]; },
          onClick: function (k) { setCross('tgroup', k, 'Territory group: ' + k); }
        }) + legendHTML(tgRows, function (r) { return pct(r.value / (a.rev || 1)); })
      }) +
      card({
        span: 'span-4', kicker: 'Assortment', title: 'Revenue by product line',
        sub: 'Only four lines ever sell; Unspecified never appears.',
        body: chartSlot('bars', {
          rows: lineRows,
          tip: function (r) { return [['Revenue', money(r.value)], ['Margin', pct(r.g.margin)], ['Share', pct(r.value / (a.rev || 1))]]; },
          onClick: function (k) { setCross('line', k, 'Product line: ' + k); }
        })
      }) +
      card({
        span: 'span-4', kicker: 'Demand', title: 'Top customer countries',
        sub: 'Customer geography from DimCustomer → DimGeography.',
        body: chartSlot('bars', {
          rows: countryRows,
          tip: function (r) { return [['Revenue', money(r.value)], ['Customers', int(r.g.customers)], ['Orders', int(r.g.orders)]]; },
          onClick: function (k) { setCross('country', k, 'Country: ' + k); }
        })
      }) +
      card({
        span: 'span-4', kicker: 'Snapshot', title: 'Operating picture',
        sub: 'Selected lines only.',
        body: '<div class="mini-kpis">' +
          '<div class="mini-kpi"><div class="k">Units</div><div class="v">' + int(a.units) + '</div></div>' +
          '<div class="mini-kpi"><div class="k">Lines</div><div class="v">' + int(a.lines) + '</div></div>' +
          '<div class="mini-kpi"><div class="k">Customers</div><div class="v">' + int(a.customers) + '</div></div>' +
          '<div class="mini-kpi"><div class="k">Freight</div><div class="v">' + money(a.freight) + '</div></div>' +
          '<div class="mini-kpi"><div class="k">Freight %</div><div class="v">' + pct(a.rev ? a.freight / a.rev : 0) + '</div></div>' +
          '<div class="mini-kpi"><div class="k">Revenue / line</div><div class="v">' + money(a.lines ? a.rev / a.lines : 0) + '</div></div>' +
          '</div>' +
          '<div class="note">Amounts are per-unit in the workbook; every total here multiplies by OrderQuantity.</div>'
      }) +
      card({
        span: 'span-12', kicker: 'Detail', title: 'Monthly performance',
        sub: 'Click a row to filter the page to that month.',
        body: table(['Month', { label: 'Revenue', cls: 'num' }, { label: 'Gross profit', cls: 'num' }, { label: 'Margin', cls: 'num' }, { label: 'MoM', cls: 'num' }], body)
      }) +
      '</div>' +
      insight(
        (lines.length
          ? '<strong>' + esc(lines[0].label) + '</strong> is the largest product line at <strong>' + money(lines[0].rev) + '</strong> (' + pct(lines[0].rev / (a.rev || 1)) + ' of revenue), while <strong>' + esc(lines[lines.length - 1].label) + '</strong> adds ' + money(lines[lines.length - 1].rev) + '. '
          : '') +
        (countries.length
          ? '<strong>' + esc(countries[0].label) + '</strong> is the biggest customer market with ' + money(countries[0].rev) + ' from ' + int(countries[0].customers) + ' customers. '
          : '') +
        'Blended margin is <strong>' + pct(a.margin) + '</strong> on ' + int(a.lines) + ' lines — ' +
        (a.margin >= 0.4 ? 'above the 40% planning watermark.' : 'below the 40% planning watermark.')
      );
  }

  /* ----------------------------------------------------------- profitability */

  function pageProfitability() {
    const R = currentRows();
    const a = agg(R);

    const mRev = new Float64Array(months.length);
    const mProfit = new Float64Array(months.length);
    for (let i = 0; i < R.length; i++) {
      const r = R[i];
      const mi = monthOf[r[0]];
      mRev[mi] += r[8];
      mProfit[mi] += r[9];
    }
    const trend = [];
    months.forEach(function (m, i) {
      if (!mRev[i]) return;
      trend.push({ key: m.key, label: m.short, value: mProfit[i] / mRev[i], rev: mRev[i], profit: mProfit[i] });
    });
    const maxMargin = trend.reduce(function (s, r) { return Math.max(s, r.value); }, 0);

    const lineGroups = groupBy(R, function (r) { return PROD_LINE[r[1]]; })
      .filter(function (g) { return g.rev > 0; })
      .sort(function (x, y) { return y.profit - x.profit; });
    const profitRows = lineGroups.map(function (g, i) {
      return { key: g.key, label: g.label, value: g.profit, color: PALETTE[i % PALETTE.length], g: g };
    });

    const productGroups = groupBy(R, function (r) { return r[1]; }, function (k) { return products[k].n; })
      .sort(function (x, y) { return y.profit - x.profit; });
    const topProducts = productGroups.slice(0, 10).map(function (g) {
      return { key: g.key, label: g.label, value: g.profit, g: g };
    });

    const marginRows = lineGroups.slice().sort(function (x, y) { return y.margin - x.margin; }).map(function (g) {
      return { key: g.key, label: g.label, value: g.margin, g: g };
    });

    const tableRows = productGroups.slice(0, 20);
    const maxRev = tableRows.reduce(function (s, g) { return Math.max(s, g.rev); }, 1);
    const body = tableRows.map(function (g) {
      return '<tr class="clickable" data-action="cross" data-kind="product" data-value="' + esc(g.key) + '" data-label="Product: ' + esc(g.label) + '">' +
        '<td>' + esc(g.label) + '</td>' +
        '<td>' + esc(PROD_LINE[g.key]) + '</td>' +
        '<td class="num">' + money(g.rev) + '</td>' +
        '<td class="num">' + money(g.profit) + '</td>' +
        '<td class="num">' + pct(g.margin) + '</td>' +
        '<td class="bar-cell"><div class="bar-track"><div class="bar-fill" style="width:' + Math.max(1, (g.rev / maxRev) * 100).toFixed(1) + '%"></div></div></td>' +
        '</tr>';
    }).join('');

    const foot = '<td>Total (top 20)</td><td></td>' +
      '<td class="num">' + money(tableRows.reduce(function (s, g) { return s + g.rev; }, 0)) + '</td>' +
      '<td class="num">' + money(tableRows.reduce(function (s, g) { return s + g.profit; }, 0)) + '</td>' +
      '<td class="num">' + pct(tableRows.reduce(function (s, g) { return s + g.rev; }, 0) ? tableRows.reduce(function (s, g) { return s + g.profit; }, 0) / tableRows.reduce(function (s, g) { return s + g.rev; }, 0) : 0) + '</td>' +
      '<td></td>';

    const best = marginRows[0];
    const worst = marginRows[marginRows.length - 1];

    return pageHead('02', 'Margin quality', 'Profitability',
      'Where the margin is made: revenue quality by product line, month and individual product, with freight cost treated as a pass-through.',
      '<strong>' + pct(a.margin) + ' blended margin</strong>' +
      money(a.profit) + ' profit on ' + money(a.rev) + ' revenue<br>Freight ' + money(a.freight) + ' (' + pct(a.rev ? a.freight / a.rev : 0) + ')') +
      crossbar() +
      kpis([
        { label: 'Gross profit', value: money(a.profit), sub: 'Margin ' + pct(a.margin) + ' · ' + int(a.units) + ' units' },
        { label: 'Gross margin', value: pct(a.margin), sub: '(Unit price − unit cost) × quantity', tone: 'teal' },
        { label: 'Revenue', value: money(a.rev), sub: int(a.lines) + ' order lines', tone: 'gold' },
        { label: 'Freight cost', value: money(a.freight), sub: pct(a.rev ? a.freight / a.rev : 0) + ' of revenue', tone: 'coral' }
      ]) +
      '<div class="grid">' +
      card({
        span: 'span-8', kicker: 'Trend', title: 'Gross margin by month',
        sub: 'Axis starts at 30% so month-to-month movement is readable; dashed line marks the blended margin.',
        body: chartSlot('area', {
          rows: trend,
          color: '#c9a227',
          labelEvery: 3,
          yMin: 0.3,
          yMax: Math.min(1, Math.ceil((maxMargin + 0.02) * 20) / 20),
          axis: function (v) { return (v * 100).toFixed(0) + '%'; },
          ref: a.margin,
          refLabel: 'Blended ' + pct(a.margin),
          tip: function (r) { return [['Margin', pct(r.value)], ['Gross profit', money(r.profit)], ['Revenue', money(r.rev)]]; }
        }, 'tall')
      }) +
      card({
        span: 'span-4', kicker: 'Mix', title: 'Profit by product line',
        sub: 'Gross profit contribution, not revenue share.',
        body: chartSlot('donut', {
          rows: profitRows,
          center: money(a.profit),
          centerLabel: 'Gross profit',
          tip: function (r) { return [['Gross profit', money(r.value)], ['Revenue', money(r.g.rev)], ['Margin', pct(r.g.margin)]]; },
          onClick: function (k) { setCross('line', k, 'Product line: ' + k); }
        }) + legendHTML(profitRows, function (r) { return pct(r.value / (a.profit || 1)); })
      }) +
      card({
        span: 'span-6', kicker: 'Products', title: 'Top 10 products by gross profit',
        sub: 'Click a bar to filter the page to that product.',
        body: chartSlot('bars', {
          rows: topProducts,
          color: '#0f766e',
          tip: function (r) { return [['Gross profit', money(r.value)], ['Revenue', money(r.g.rev)], ['Margin', pct(r.g.margin)], ['Units', int(r.g.units)]]; },
          onClick: function (k) { setCross('product', k, 'Product: ' + products[k].n); }
        })
      }) +
      card({
        span: 'span-6', kicker: 'Lines', title: 'Margin by product line',
        sub: 'Ordered best to worst margin in the current selection.',
        body: chartSlot('bars', {
          rows: marginRows,
          color: '#1b3550',
          fmt: pct1,
          tip: function (r) { return [['Margin', pct(r.value)], ['Gross profit', money(r.g.profit)], ['Revenue', money(r.g.rev)]]; },
          onClick: function (k) { setCross('line', k, 'Product line: ' + k); }
        })
      }) +
      card({
        span: 'span-12', kicker: 'Detail', title: 'Top 20 products by revenue',
        sub: 'Bar shows revenue relative to the largest product in the table.',
        body: table(
          ['Product', 'Line', { label: 'Revenue', cls: 'num' }, { label: 'Profit', cls: 'num' }, { label: 'Margin', cls: 'num' }, { label: 'Scale', cls: 'bar-cell' }],
          body || '<tr><td colspan="6" class="empty-cell">No products in the current selection.</td></tr>',
          foot
        )
      }) +
      '</div>' +
      insight(
        (best ? '<strong>' + esc(best.label) + '</strong> carries the strongest margin at <strong>' + pct(best.value) + '</strong> (' + money(best.g.profit) + ' profit), ' : '') +
        (worst && marginRows.length > 1 ? 'while <strong>' + esc(worst.label) + '</strong> trails at ' + pct(worst.value) + '. ' : '') +
        'Freight adds ' + money(a.freight) + ' (' + pct(a.rev ? a.freight / a.rev : 0) + ' of revenue) and is reported separately — the source TaxAmt/Freight columns are per unit, so both are multiplied by quantity.'
      );
  }

  /* --------------------------------------------------------------- customers */

  function pageCustomers() {
    const R = currentRows();
    const a = agg(R);
    const rep = repeatStats(R);

    const bandOrder = {};
    INCOME_BANDS.forEach(function (b, i) { bandOrder[b.key] = i; });
    const bands = groupBy(R, function (r) { return CUST_BAND[r[2]]; }, bandLabel)
      .sort(function (x, y) { return bandOrder[x.key] - bandOrder[y.key]; });
    const bandRows = bands.map(function (g, i) {
      return { key: g.key, label: g.label, value: g.rev, color: PALETTE[i % PALETTE.length], g: g };
    });

    const genders = groupBy(R, function (r) { return customers[r[2]].gender; }, genderLabel)
      .sort(function (x, y) { return y.rev - x.rev; });
    const genderRows = genders.map(function (g, i) {
      return { key: g.key, label: g.label, value: g.rev, color: [PALETTE[0], PALETTE[1], PALETTE[2]][i % 3], g: g };
    });

    const vOrder = {};
    VBANDS.forEach(function (b, i) { vOrder[b.key] = i; });
    const vb = groupBy(R, function (r) { return CUST_VBAND[r[2]]; }, function (k) {
      const b = VBANDS.find(function (x) { return x.key === k; });
      return b ? b.label : k;
    }).sort(function (x, y) { return vOrder[x.key] - vOrder[y.key]; });
    const vbRows = vb.map(function (g, i) {
      return { key: g.key, label: g.label, value: g.rev, color: PALETTE[(i + 2) % PALETTE.length], g: g };
    });

    const custGroups = groupBy(R, function (r) { return r[2]; }, function (k) { return customers[k].n; })
      .sort(function (x, y) { return y.rev - x.rev; });
    const topCust = custGroups.slice(0, 10);
    const maxCustRev = topCust.reduce(function (s, g) { return Math.max(s, g.rev); }, 1);

    const body = topCust.map(function (g, i) {
      const c = customers[g.key];
      return '<tr class="clickable" data-action="cross" data-kind="customer" data-value="' + esc(g.key) + '" data-label="Customer: ' + esc(c.n) + '">' +
        '<td class="rank">' + (i + 1) + '</td>' +
        '<td><span class="customer-name">' + esc(c.n) + '</span><span class="customer-sub">' + esc(c.alt) + '</span></td>' +
        '<td>' + esc(CUST_COUNTRY[g.key]) + '</td>' +
        '<td class="num">' + money(c.income) + '</td>' +
        '<td class="num">' + int(g.orders) + '</td>' +
        '<td class="num">' + money(g.rev) + '</td>' +
        '<td class="num">' + money(g.profit) + '</td>' +
        '<td class="bar-cell"><div class="bar-track"><div class="bar-fill" style="width:' + Math.max(1, (g.rev / maxCustRev) * 100).toFixed(1) + '%"></div></div></td>' +
        '</tr>';
    }).join('');

    const foot = '<td></td><td>Total (top 10)</td><td></td><td></td>' +
      '<td class="num">' + int(topCust.reduce(function (s, g) { return s + g.orders; }, 0)) + '</td>' +
      '<td class="num">' + money(topCust.reduce(function (s, g) { return s + g.rev; }, 0)) + '</td>' +
      '<td class="num">' + money(topCust.reduce(function (s, g) { return s + g.profit; }, 0)) + '</td><td></td>';

    return pageHead('03', 'Customer base', 'Customers',
      'Who buys: income band, gender and lifetime value quartile — with repeat behaviour measured as customers placing two or more orders.',
      '<strong>' + int(a.customers) + ' buyers in view</strong>' +
      int(rep.repeat) + ' repeat · ' + pct(rep.rate) + '<br>' + money(a.rev / (a.customers || 1)) + ' revenue per customer') +
      crossbar() +
      kpis([
        { label: 'Customers', value: int(a.customers), sub: int(rep.customers) + ' distinct buyers · ' + int(a.orders) + ' orders' },
        { label: 'Repeat rate', value: pct(rep.rate), sub: int(rep.repeat) + ' customers with 2+ orders', tone: 'teal' },
        { label: 'Revenue per customer', value: money(a.rev / (a.customers || 1)), sub: money(a.profit / (a.customers || 1)) + ' profit per customer', tone: 'gold' },
        { label: 'Orders per customer', value: dec(a.orders / (a.customers || 1)), sub: 'AOV ' + money(a.aov), tone: 'green' }
      ]) +
      '<div class="grid">' +
      card({
        span: 'span-4', kicker: 'Segment', title: 'Revenue by income band',
        sub: 'Bands are derived from YearlyIncome at runtime.',
        body: chartSlot('bars', {
          rows: bandRows,
          tip: function (r) { return [['Revenue', money(r.value)], ['Customers', int(r.g.customers)], ['Margin', pct(r.g.margin)]]; },
          onClick: function (k) { setCross('band', k, 'Income band: ' + bandLabel(k)); }
        })
      }) +
      card({
        span: 'span-4', kicker: 'Segment', title: 'Revenue by gender',
        sub: 'Customer gender from DimCustomer.',
        body: chartSlot('donut', {
          rows: genderRows,
          center: money(a.rev),
          centerLabel: 'Revenue',
          tip: function (r) { return [['Revenue', money(r.value)], ['Customers', int(r.g.customers)], ['Share', pct(r.value / (a.rev || 1))]]; },
          onClick: function (k) { setCross('gender', k, 'Gender: ' + genderLabel(k)); }
        }) + legendHTML(genderRows, function (r) { return pct(r.value / (a.rev || 1)); })
      }) +
      card({
        span: 'span-4', kicker: 'Value', title: 'Revenue by lifetime value quartile',
        sub: 'Quartiles of each customer\'s lifetime revenue: ' + money(Q1) + ' / ' + money(Q2) + ' / ' + money(Q3) + '.',
        body: chartSlot('bars', {
          rows: vbRows,
          tip: function (r) { return [['Revenue', money(r.value)], ['Customers', int(r.g.customers)], ['Orders', int(r.g.orders)]]; },
          onClick: function (k) {
            const b = VBANDS.find(function (x) { return x.key === k; });
            setCross('vband', k, 'Lifetime value: ' + (b ? b.label : k));
          }
        })
      }) +
      card({
        span: 'span-12', kicker: 'Detail', title: 'Top 10 customers by revenue',
        sub: 'Click a customer to filter the page; membership tiers are not in the workbook, so none are implied.',
        body: table(
          [{ label: '#', cls: 'rank' }, 'Customer', 'Country', { label: 'Yearly income', cls: 'num' }, { label: 'Orders', cls: 'num' }, { label: 'Revenue', cls: 'num' }, { label: 'Profit', cls: 'num' }, { label: 'Scale', cls: 'bar-cell' }],
          body || '<tr><td colspan="8" class="empty-cell">No customers in the current selection.</td></tr>',
          foot
        )
      }) +
      '</div>' +
      insight(
        (bandRows.length
          ? '<strong>' + esc(bandRows[0].label) + '</strong> income band leads with <strong>' + money(bandRows[0].value) + '</strong> from ' + int(bandRows[0].g.customers) + ' customers. '
          : '') +
        (genderRows.length
          ? esc(genderRows[0].label) + ' customers account for ' + pct(genderRows[0].value / (a.rev || 1)) + ' of revenue. '
          : '') +
        'Repeat rate is <strong>' + pct(rep.rate) + '</strong>: ' + int(rep.repeat) + ' of ' + int(rep.customers) + ' buyers placed a second order in the selected period.'
      );
  }

  /* --------------------------------------------------------------- geography */

  function pageGeography() {
    const R = currentRows();
    const a = agg(R);

    const countries = groupBy(R, function (r) { return CUST_COUNTRY[r[2]]; }).sort(function (x, y) { return y.rev - x.rev; });
    const countryRows = countries.map(function (g) {
      return { key: g.key, label: g.label, value: g.rev, g: g };
    });

    const groups = groupBy(R, function (r) { return territories[r[3]].group; }).sort(function (x, y) { return y.rev - x.rev; });
    const years = [];
    for (let i = 0; i < R.length; i++) {
      const y = yearOf[R[i][0]];
      if (years.indexOf(y) === -1) years.push(y);
    }
    years.sort();
    const cell = new Map();
    let maxCell = 1;
    for (let i = 0; i < R.length; i++) {
      const r = R[i];
      const k = territories[r[3]].group + '|' + yearOf[r[0]];
      let c = cell.get(k);
      if (!c) { c = { rev: 0, profit: 0 }; cell.set(k, c); }
      c.rev += r[8]; c.profit += r[9];
      if (c.rev > maxCell) maxCell = c.rev;
    }

    let heat = '<table class="heat"><thead><tr><th class="rowhead">Territory group</th>' +
      years.map(function (y) { return '<th>' + y + '</th>'; }).join('') + '<th>Total</th></tr></thead><tbody>';
    groups.forEach(function (g) {
      heat += '<tr><th class="rowhead">' + esc(g.label) + '</th>';
      years.forEach(function (y) {
        const c = cell.get(g.key + '|' + y);
        if (!c) { heat += '<td class="empty-cell">—</td>'; return; }
        const alpha = 0.10 + 0.45 * (c.rev / maxCell);
        const sel = state.cross && state.cross.kind === 'tgroup' && state.cross.value === g.key ? ' sel' : '';
        heat += '<td class="' + sel.trim() + '" data-action="cross" data-kind="tgroup" data-value="' + esc(g.key) + '" data-label="Territory group: ' + esc(g.key) + '" style="background:rgba(15,118,110,' + alpha.toFixed(3) + ')">' +
          '<span class="h-rev">' + money(c.rev) + '</span><span class="h-sub">' + pct(c.rev ? c.profit / c.rev : 0) + '</span></td>';
      });
      heat += '<td class="total-cell">' + money(g.rev) + '</td></tr>';
    });
    heat += '</tbody></table>';

    const terr = groupBy(R, function (r) { return r[3]; }, function (k) { return territories[k].region; })
      .sort(function (x, y) { return y.rev - x.rev; });
    const maxTerr = terr.reduce(function (s, g) { return Math.max(s, g.rev); }, 1);
    const body = terr.map(function (g) {
      const t = territories[g.key];
      return '<tr class="clickable" data-action="cross" data-kind="territory" data-value="' + esc(g.key) + '" data-label="Territory: ' + esc(t.region) + '">' +
        '<td><span class="customer-name">' + esc(t.region) + '</span></td>' +
        '<td>' + esc(t.group) + '</td>' +
        '<td>' + esc(t.country) + '</td>' +
        '<td class="num">' + money(g.rev) + '</td>' +
        '<td class="num">' + money(g.profit) + '</td>' +
        '<td class="num">' + pct(g.margin) + '</td>' +
        '<td class="num">' + int(g.orders) + '</td>' +
        '<td class="bar-cell"><div class="bar-track"><div class="bar-fill" style="width:' + Math.max(1, (g.rev / maxTerr) * 100).toFixed(1) + '%"></div></div></td>' +
        '</tr>';
    }).join('');

    const totalRev = terr.reduce(function (s, g) { return s + g.rev; }, 0);
    const totalProfit = terr.reduce(function (s, g) { return s + g.profit; }, 0);
    const foot = '<td>Total</td><td></td><td></td>' +
      '<td class="num">' + money(totalRev) + '</td>' +
      '<td class="num">' + money(totalProfit) + '</td>' +
      '<td class="num">' + pct(totalRev ? totalProfit / totalRev : 0) + '</td>' +
      '<td class="num">' + int(a.orders) + '</td><td></td>';

    return pageHead('04', 'Market coverage', 'Geography',
      'Territory performance straight from the fact key, paired with customer country from the customer dimension — the two paths are never mixed in one visual.',
      '<strong>' + int(countries.length) + ' customer countries</strong>' +
      int(terr.length) + ' sales territories<br>' + int(a.customers) + ' customers in view') +
      crossbar() +
      kpis([
        { label: 'Revenue', value: money(a.rev), sub: int(a.lines) + ' lines across ' + int(countries.length) + ' countries' },
        { label: 'Gross margin', value: pct(a.margin), sub: money(a.profit) + ' gross profit', tone: 'teal' },
        { label: 'Territories', value: int(terr.length), sub: int(groups.length) + ' territory groups', tone: 'gold' },
        { label: 'Orders', value: int(a.orders), sub: 'AOV ' + money(a.aov), tone: 'green' }
      ]) +
      '<div class="grid">' +
      card({
        span: 'span-7', kicker: 'Market', title: 'Revenue by customer country',
        sub: 'Geography reached through DimCustomer — independent of the sales-territory key.',
        body: chartSlot('bars', {
          rows: countryRows,
          tip: function (r) { return [['Revenue', money(r.value)], ['Customers', int(r.g.customers)], ['Margin', pct(r.g.margin)]]; },
          onClick: function (k) { setCross('country', k, 'Country: ' + k); }
        }, 'tall')
      }) +
      card({
        span: 'span-5', kicker: 'Matrix', title: 'Territory group × year',
        sub: 'Colour intensity follows revenue; click a cell to filter the page.',
        body: '<div style="margin-top:10px">' + (groups.length ? heat : emptyChart('No territory data in the current selection.')) + '</div>' +
          '<div class="note">Sales territory key 11 (NA) exists in the dimension but is never used by a fact row.</div>'
      }) +
      card({
        span: 'span-12', kicker: 'Detail', title: 'Territory performance',
        sub: 'Click a row to filter the page to that territory.',
        body: table(
          ['Territory', 'Group', 'Country', { label: 'Revenue', cls: 'num' }, { label: 'Profit', cls: 'num' }, { label: 'Margin', cls: 'num' }, { label: 'Orders', cls: 'num' }, { label: 'Scale', cls: 'bar-cell' }],
          body || '<tr><td colspan="8" class="empty-cell">No territories in the current selection.</td></tr>',
          foot
        )
      }) +
      '</div>' +
      insight(
        (countries.length ? '<strong>' + esc(countries[0].label) + '</strong> is the largest customer market at ' + money(countries[0].rev) + ' (' + pct(countries[0].rev / (a.rev || 1)) + ' of revenue). ' : '') +
        (groups.length ? 'By sales territory, <strong>' + esc(groups[0].label) + '</strong> leads with ' + money(groups[0].rev) + '. ' : '') +
        'Territory visuals read <strong>FactInternetSales[SalesTerritoryKey]</strong>; country visuals read the customer dimension, so the two never argue over the same filter path.'
      );
  }

  /* ------------------------------------------------------------------ detail */

  const SORTERS = {
    date: function (r) { return r[0]; },
    order: function (r) { return AW.orders[r[4]] + '-' + String(1000 + r[13]); },
    product: function (r) { return products[r[1]].n; },
    customer: function (r) { return customers[r[2]].n; },
    qty: function (r) { return r[5]; },
    revenue: function (r) { return r[8]; },
    profit: function (r) { return r[9]; },
    margin: function (r) { return r[8] ? r[9] / r[8] : 0; },
    lead: function (r) { return r[11]; }
  };

  function sortTh(key, label, cls) {
    const on = state.sort.key === key;
    const arrow = on ? (state.sort.dir > 0 ? '▲' : '▼') : '';
    return '<th' + (cls ? ' class="' + cls + '"' : '') + '><button class="sort-btn" data-action="sort" data-value="' + key + '">' +
      esc(label) + '<span class="arrow">' + arrow + '</span></button></th>';
  }

  function pageDetail() {
    const R = currentRows();
    let units = 0, rev = 0, profit = 0, lead = 0, late = 0;
    for (let i = 0; i < R.length; i++) {
      const r = R[i];
      units += r[5]; rev += r[8]; profit += r[9]; lead += r[11];
      if (r[12] > 0) late++;
    }
    const avgLead = R.length ? lead / R.length : 0;
    const lateRate = R.length ? late / R.length : 0;

    const get = SORTERS[state.sort.key] || SORTERS.date;
    const dir = state.sort.dir;
    const sorted = R.slice().sort(function (x, y) {
      const vx = get(x), vy = get(y);
      if (typeof vx === 'string' || typeof vy === 'string') {
        return String(vx).localeCompare(String(vy)) * dir;
      }
      return (vx - vy) * dir;
    });

    const size = state.pageSize;
    const total = sorted.length;
    const maxPage = Math.max(0, Math.ceil(total / size) - 1);
    if (state.pageIdx > maxPage) state.pageIdx = maxPage;
    const start = state.pageIdx * size;
    const pageRows = sorted.slice(start, start + size);

    const body = pageRows.map(function (r) {
      const p = products[r[1]];
      const c = customers[r[2]];
      const t = territories[r[3]];
      const margin = r[8] ? r[9] / r[8] : 0;
      return '<tr>' +
        '<td>' + esc(dates[r[0]]) + '</td>' +
        '<td><span class="customer-name">' + esc(AW.orders[r[4]]) + '</span><span class="customer-sub">line ' + esc(r[13]) + '</span></td>' +
        '<td><span class="prod-name">' + esc(p.n) + '</span><span class="prod-sub">' + esc(PROD_LINE[r[1]]) + ' · ' + esc(p.model || '—') + '</span></td>' +
        '<td><span class="customer-name">' + esc(c.n) + '</span><span class="customer-sub">' + esc(CUST_COUNTRY[r[2]]) + ' · ' + esc(t.region) + '</span></td>' +
        '<td class="num">' + int(r[5]) + '</td>' +
        '<td class="num">' + moneyFull(r[8]) + '</td>' +
        '<td class="num">' + moneyFull(r[9]) + '</td>' +
        '<td class="num">' + pct1(margin) + '</td>' +
        '<td class="num' + (r[12] > 0 ? ' neg' : '') + '">' + int(r[11]) + '</td>' +
        '</tr>';
    }).join('');

    const showing = total ? (start + 1) + '–' + (start + pageRows.length) + ' of ' + int(total) : '0 of 0';
    const foot = '<td colspan="4">Filtered totals</td>' +
      '<td class="num">' + int(units) + '</td>' +
      '<td class="num">' + moneyFull(rev) + '</td>' +
      '<td class="num">' + moneyFull(profit) + '</td>' +
      '<td class="num">' + pct1(rev ? profit / rev : 0) + '</td>' +
      '<td class="num">' + dec(avgLead) + '</td>';

    const controls =
      '<button class="btn" type="button" data-action="prev"' + (state.pageIdx <= 0 ? ' style="opacity:.45"' : '') + '>← Prev</button>' +
      '<span class="hint">' + showing + '</span>' +
      '<button class="btn" type="button" data-action="next"' + (state.pageIdx >= maxPage ? ' style="opacity:.45"' : '') + '>Next →</button>';

    const toolbar = '<div class="toolbar">' +
      '<span class="toolbar-label">Sort</span>' +
      '<select data-select="sort">' +
      [['date', 'Order date'], ['revenue', 'Revenue'], ['profit', 'Profit'], ['margin', 'Margin'], ['qty', 'Quantity'], ['product', 'Product'], ['customer', 'Customer'], ['lead', 'Lead days']]
        .map(function (o) { return '<option value="' + o[0] + '"' + (state.sort.key === o[0] ? ' selected' : '') + '>' + o[1] + '</option>'; }).join('') +
      '</select>' +
      '<span class="sep"></span>' +
      '<span class="toolbar-label">Rows</span>' +
      '<select data-select="pagesize">' +
      [25, 50, 100].map(function (n) { return '<option value="' + n + '"' + (state.pageSize === n ? ' selected' : '') + '>' + n + ' per page</option>'; }).join('') +
      '</select>' +
      '<span class="sep"></span>' +
      '<button class="ghost-btn" type="button" data-action="export">Export this view</button>' +
      '<span class="pill-soft" style="margin-left:auto">' + int(R.length) + ' lines match the current filters</span>' +
      '</div>';

    return pageHead('05', 'Line-level exploration', 'Detail',
      'Every order line behind the totals: 60,398 rows joined to product, customer and territory, sortable and exportable.',
      '<strong>' + int(R.length) + ' lines in view</strong>' +
      int(units) + ' units · ' + money(rev) + ' revenue<br>' + money(profit) + ' gross profit') +
      crossbar() +
      kpis([
        { label: 'Order lines', value: int(R.length), sub: 'Grain: order number + line number' },
        { label: 'Units', value: int(units), sub: 'Sum of OrderQuantity', tone: 'teal' },
        { label: 'Average lead time', value: dec(avgLead) + ' d', sub: 'Order date → ship date', tone: 'gold' },
        { label: 'Late line rate', value: pct(lateRate), sub: int(late) + ' lines shipped after due date', tone: 'coral' }
      ]) +
      toolbar +
      card({
        span: 'span-12', kicker: 'Explorer', title: 'Order line explorer',
        sub: 'Click a column heading to sort. Amounts are line totals (unit price × quantity).',
        actions: controls,
        body: table(
          [
            { html: sortTh('date', 'Date') },
            { html: sortTh('order', 'Order') },
            { html: sortTh('product', 'Product') },
            { html: sortTh('customer', 'Customer') },
            { html: sortTh('qty', 'Qty', 'num') },
            { html: sortTh('revenue', 'Revenue', 'num') },
            { html: sortTh('profit', 'Profit', 'num') },
            { html: sortTh('margin', 'Margin', 'num') },
            { html: sortTh('lead', 'Lead days', 'num') }
          ],
          body || '<tr><td colspan="9" class="empty-cell">No order lines match the current filters.</td></tr>',
          foot
        )
      }) +
      insight(
        'The explorer is the reconciliation surface: the footer totals above must equal the KPI cards and every other page at the same filter state. ' +
        'Late lines are <strong>' + int(late) + '</strong> (' + pct(lateRate) + ') — every line in this extract ships on or before its due date, so the KPI renders 0 rather than blank.'
      );
  }

  /* ------------------------------------------------------------------ render */

  function render() {
    const main = document.getElementById('app');
    if (!main) return;
    chartQueue = [];
    chartSeq = 0;
    let html = '';
    switch (state.page) {
      case 'profitability': html = pageProfitability(); break;
      case 'customers': html = pageCustomers(); break;
      case 'geography': html = pageGeography(); break;
      case 'detail': html = pageDetail(); break;
      default: html = pageOverview();
    }
    main.innerHTML = html;
    flushCharts();
    syncChrome();
  }

  /* ------------------------------------------------------------------ chrome */

  const els = {
    app: document.getElementById('app'),
    tabs: document.getElementById('tabs'),
    chips: document.getElementById('chips'),
    filters: document.getElementById('filters'),
    presets: document.getElementById('presets'),
    from: document.getElementById('dateFrom'),
    to: document.getElementById('dateTo'),
    modal: document.getElementById('modal'),
    modalBody: document.getElementById('modalBody'),
    footerMeta: document.getElementById('footerMeta'),
    notesBtn: document.getElementById('notesBtn'),
    exportBtn: document.getElementById('exportBtn')
  };

  function chipsHTML() {
    const items = [];
    if (state.from !== 0 || state.to !== dates.length - 1) {
      items.push({ action: 'clear-period', label: 'Period: ' + dates[state.from] + ' → ' + dates[state.to] });
    }
    state.countries.forEach(function (v) { items.push({ action: 'chip', kind: 'countries', value: v, label: 'Country: ' + v }); });
    state.lines.forEach(function (v) { items.push({ action: 'chip', kind: 'lines', value: v, label: 'Line: ' + v }); });
    state.genders.forEach(function (v) { items.push({ action: 'chip', kind: 'genders', value: v, label: 'Gender: ' + genderLabel(v) }); });
    state.bands.forEach(function (v) { items.push({ action: 'chip', kind: 'bands', value: v, label: 'Income: ' + bandLabel(v) }); });

    if (!items.length) return '<span class="chips-empty">No filters applied</span>';
    return items.map(function (it) {
      return '<span class="chip">' + esc(it.label) +
        '<button type="button" data-action="' + it.action + '"' +
        (it.kind ? ' data-kind="' + it.kind + '" data-value="' + esc(it.value) + '"' : '') +
        ' aria-label="Remove filter">×</button></span>';
    }).join('');
  }

  function syncMenuChecks() {
    if (!els.filters) return;
    const boxes = els.filters.querySelectorAll('input[data-filter]');
    for (let i = 0; i < boxes.length; i++) {
      const kind = boxes[i].getAttribute('data-filter');
      const set = state[kind];
      boxes[i].checked = !!(set && set.has(boxes[i].value));
    }
  }

  function activePreset() {
    const last = dates.length - 1;
    if (state.from === 0 && state.to === last) return 'all';
    if (state.from === 0 && state.to === dates.indexOf('2021-12-31')) return '2021';
    if (state.from === dates.indexOf('2022-01-01') && state.to === last) return '2022';
    if (state.from === dates.indexOf('2022-07-01') && state.to === last) return 'h2';
    return null;
  }

  function syncChrome() {
    if (els.tabs) {
      const tabs = els.tabs.querySelectorAll('[data-page]');
      for (let i = 0; i < tabs.length; i++) {
        const on = tabs[i].getAttribute('data-page') === state.page;
        tabs[i].classList.toggle('active', on);
        tabs[i].setAttribute('aria-selected', on ? 'true' : 'false');
      }
    }
    if (els.from && els.from.value !== dates[state.from]) els.from.value = dates[state.from];
    if (els.to && els.to.value !== dates[state.to]) els.to.value = dates[state.to];

    const preset = activePreset();
    if (els.presets) {
      const btns = els.presets.querySelectorAll('[data-preset]');
      for (let i = 0; i < btns.length; i++) {
        btns[i].classList.toggle('active', btns[i].getAttribute('data-preset') === preset);
      }
    }

    if (els.chips) els.chips.innerHTML = chipsHTML();

    [
      ['countries', state.countries],
      ['lines', state.lines],
      ['genders', state.genders],
      ['bands', state.bands]
    ].forEach(function (pair) {
      const kind = pair[0], set = pair[1];
      const badge = document.querySelector('[data-count="' + kind + '"]');
      if (badge) badge.textContent = set.size ? set.size + ' selected' : 'All';
      const det = document.querySelector('details.ms[data-filter="' + kind + '"]');
      if (det) det.setAttribute('data-active', set.size ? 'true' : 'false');
    });
    syncMenuChecks();
  }

  /* -------------------------------------------------------------- filter ui */

  function menuHTML(kind, entries) {
    return entries.map(function (e) {
      return '<label><input type="checkbox" data-filter="' + kind + '" value="' + esc(e.value) + '">' +
        '<span>' + esc(e.label) + '</span>' +
        '<span class="ms-count" style="margin-left:auto">' + int(e.count) + '</span></label>';
    }).join('') +
      '<button type="button" class="ms-clear" data-action="clear-kind" data-kind="' + kind + '">Clear selection</button>';
  }

  function buildMenus() {
    const counts = { countries: new Map(), lines: new Map(), genders: new Map(), bands: new Map() };
    function bump(map, k) { map.set(k, (map.get(k) || 0) + 1); }
    for (let i = 0; i < N; i++) {
      const r = fact[i];
      bump(counts.countries, CUST_COUNTRY[r[2]]);
      bump(counts.lines, PROD_LINE[r[1]]);
      bump(counts.genders, customers[r[2]].gender);
      bump(counts.bands, CUST_BAND[r[2]]);
    }

    const countryEntries = Array.from(counts.countries, function (p) { return { value: p[0], label: p[0], count: p[1] }; })
      .sort(function (a, b) { return b.count - a.count; });
    const lineEntries = Array.from(counts.lines, function (p) { return { value: p[0], label: p[0], count: p[1] }; })
      .sort(function (a, b) { return b.count - a.count; });
    const genderEntries = ['M', 'F'].filter(function (g) { return counts.genders.has(g); })
      .map(function (g) { return { value: g, label: genderLabel(g), count: counts.genders.get(g) }; });
    const bandEntries = INCOME_BANDS.filter(function (b) { return counts.bands.has(b.key); })
      .map(function (b) { return { value: b.key, label: b.label, count: counts.bands.get(b.key) }; });

    const targets = {
      countries: document.getElementById('menuCountries'),
      lines: document.getElementById('menuLines'),
      genders: document.getElementById('menuGenders'),
      bands: document.getElementById('menuBands')
    };
    if (targets.countries) targets.countries.innerHTML = menuHTML('countries', countryEntries);
    if (targets.lines) targets.lines.innerHTML = menuHTML('lines', lineEntries);
    if (targets.genders) targets.genders.innerHTML = menuHTML('genders', genderEntries);
    if (targets.bands) targets.bands.innerHTML = menuHTML('bands', bandEntries);
  }

  function applyPreset(name) {
    const last = dates.length - 1;
    let from = 0, to = last;
    if (name === '2021') { from = 0; to = dates.indexOf('2021-12-31'); }
    else if (name === '2022') { from = dates.indexOf('2022-01-01'); to = last; }
    else if (name === 'h2') { from = dates.indexOf('2022-07-01'); to = last; }
    state.from = Math.max(0, from);
    state.to = Math.max(state.from, to);
    state.pageIdx = 0;
    render();
  }

  function onDateChange() {
    let f = dates.indexOf(els.from.value);
    let t = dates.indexOf(els.to.value);
    if (f < 0) f = 0;
    if (t < 0) t = dates.length - 1;
    if (f > t) { const tmp = f; f = t; t = tmp; }
    state.from = f;
    state.to = t;
    state.pageIdx = 0;
    render();
  }

  /* ------------------------------------------------------------------ events */

  function bindChrome() {
    if (els.tabs) {
      els.tabs.addEventListener('click', function (ev) {
        const b = ev.target.closest('[data-page]');
        if (!b) return;
        state.page = b.getAttribute('data-page');
        state.cross = null;
        state.pageIdx = 0;
        try { history.replaceState(null, '', '#' + state.page); } catch (e) { /* file:// */ }
        render();
      });
    }

    if (els.presets) {
      els.presets.addEventListener('click', function (ev) {
        const b = ev.target.closest('[data-preset]');
        if (!b) return;
        applyPreset(b.getAttribute('data-preset'));
      });
    }

    if (els.from) els.from.addEventListener('change', onDateChange);
    if (els.to) els.to.addEventListener('change', onDateChange);

    if (els.filters) {
      els.filters.addEventListener('change', function (ev) {
        const cb = ev.target.closest('input[data-filter]');
        if (!cb) return;
        const kind = cb.getAttribute('data-filter');
        const set = state[kind];
        if (!set) return;
        if (cb.checked) set.add(cb.value); else set.delete(cb.value);
        state.pageIdx = 0;
        render();
      });
      els.filters.addEventListener('click', function (ev) {
        const btn = ev.target.closest('[data-action="clear-kind"]');
        if (!btn) return;
        const kind = btn.getAttribute('data-kind');
        if (state[kind]) state[kind].clear();
        state.pageIdx = 0;
        render();
      });
    }

    if (els.chips) {
      els.chips.addEventListener('click', function (ev) {
        const t = ev.target.closest('[data-action]');
        if (!t) return;
        const act = t.getAttribute('data-action');
        if (act === 'chip') {
          const kind = t.getAttribute('data-kind');
          const value = t.getAttribute('data-value');
          if (state[kind]) state[kind].delete(value);
          state.pageIdx = 0;
          render();
        } else if (act === 'clear-period') {
          state.from = 0;
          state.to = dates.length - 1;
          state.pageIdx = 0;
          render();
        }
      });
    }

    const resetBtn = document.getElementById('resetFilters');
    if (resetBtn) {
      resetBtn.addEventListener('click', function () {
        state.countries.clear();
        state.lines.clear();
        state.genders.clear();
        state.bands.clear();
        state.from = 0;
        state.to = dates.length - 1;
        state.cross = null;
        state.pageIdx = 0;
        render();
        toast('All filters reset');
      });
    }

    document.addEventListener('click', function (ev) {
      if (ev.target.closest && ev.target.closest('details.ms')) return;
      const open = document.querySelectorAll('details.ms[open]');
      for (let i = 0; i < open.length; i++) open[i].removeAttribute('open');
    });

    if (els.app) {
      els.app.addEventListener('click', function (ev) {
        const t = ev.target.closest('[data-action]');
        if (!t) return;
        const act = t.getAttribute('data-action');

        if (act === 'clear-cross') { clearCross(); return; }

        if (act === 'cross') {
          setCross(t.getAttribute('data-kind'), t.getAttribute('data-value'), t.getAttribute('data-label'));
          return;
        }

        if (act === 'month') {
          const i = Number(t.getAttribute('data-value'));
          const m = months[i];
          if (!m) return;
          const c = state.cross;
          if (c && c.kind === 'month' && c.i === i) state.cross = null;
          else state.cross = { kind: 'month', value: m.key, label: 'Month: ' + m.label, i: i };
          state.pageIdx = 0;
          render();
          return;
        }

        if (act === 'sort') {
          const key = t.getAttribute('data-value');
          if (state.sort.key === key) state.sort.dir = -state.sort.dir;
          else {
            state.sort.key = key;
            state.sort.dir = (key === 'product' || key === 'customer' || key === 'order') ? 1 : -1;
          }
          state.pageIdx = 0;
          render();
          return;
        }

        if (act === 'prev') { state.pageIdx = Math.max(0, state.pageIdx - 1); render(); return; }
        if (act === 'next') { state.pageIdx += 1; render(); return; }
        if (act === 'export') { exportCsv(); return; }

        if (act === 'chip') {
          const kind = t.getAttribute('data-kind');
          const value = t.getAttribute('data-value');
          if (state[kind]) state[kind].delete(value);
          state.pageIdx = 0;
          render();
          return;
        }

        if (act === 'clear-period') {
          state.from = 0;
          state.to = dates.length - 1;
          state.pageIdx = 0;
          render();
        }
      });

      els.app.addEventListener('change', function (ev) {
        const sel = ev.target.closest('select[data-select]');
        if (!sel) return;
        const which = sel.getAttribute('data-select');
        if (which === 'sort') {
          state.sort.key = sel.value;
          state.sort.dir = -1;
          state.pageIdx = 0;
          render();
        } else if (which === 'pagesize') {
          state.pageSize = Number(sel.value) || 25;
          state.pageIdx = 0;
          render();
        }
      });
    }

    document.addEventListener('keydown', function (ev) {
      if (ev.key !== 'Escape') return;
      if (els.modal && !els.modal.hidden) { closeModal(); return; }
      if (state.cross) { clearCross(); return; }
      const open = document.querySelectorAll('details.ms[open]');
      for (let i = 0; i < open.length; i++) open[i].removeAttribute('open');
    });

    let rt = null;
    window.addEventListener('resize', function () {
      clearTimeout(rt);
      rt = setTimeout(render, 180);
    });
  }

  /* ------------------------------------------------------------ notes / modal */

  const REVIEW_KEY = 'aw.internetSales.review.v1';

  function integrity() {
    let sumRev = 0, sumProfit = 0, sumUnits = 0, badQty = 0, late = 0, unresolved = 0;
    const orders = new Set(), custs = new Set(), lines = new Set();
    for (let i = 0; i < N; i++) {
      const r = fact[i];
      sumRev += r[8];
      sumProfit += r[9];
      sumUnits += r[5];
      if (Math.abs(r[8] - r[6] * r[5]) > 0.005) badQty++;
      if (r[12] > 0) late++;
      orders.add(r[4]);
      custs.add(r[2]);
      lines.add(AW.orders[r[4]] + '|' + r[13]);
      const p = products[r[1]];
      const c = customers[r[2]];
      const t = territories[r[3]];
      if (!p || !c || !t || !geos[c.geo]) unresolved++;
    }
    return {
      rows: N, sumRev: sumRev, sumProfit: sumProfit, sumUnits: sumUnits, badQty: badQty,
      late: late, unresolved: unresolved, orders: orders.size, customers: custs.size, uniqueLines: lines.size
    };
  }

  function checkHTML(label, value, ok) {
    return '<div class="check"><span>' + esc(label) + '</span><span><b>' + esc(value) + '</b> ' +
      '<span class="badge-' + (ok ? 'pass' : 'fail') + '">' + (ok ? 'Pass' : 'Fail') + '</span></span></div>';
  }

  function notesHTML() {
    const I = integrity();
    const near = function (a, b) { return Math.abs(a - b) < 0.01; };

    const checks = [
      checkHTML('Fact rows', int(I.rows), I.rows === meta.rows),
      checkHTML('Revenue  Σ(unit price × qty)', moneyFull(I.sumRev), near(I.sumRev, meta.revenue)),
      checkHTML('Gross profit  Σ((price − cost) × qty)', moneyFull(I.sumProfit), near(I.sumProfit, meta.profit)),
      checkHTML('Units  Σ quantity', int(I.sumUnits), near(I.sumUnits, meta.units)),
      checkHTML('Distinct orders', int(I.orders), I.orders === meta.orders),
      checkHTML('Distinct customers', int(I.customers), I.customers === meta.customers),
      checkHTML('Order lines unique on order + line', int(I.uniqueLines), I.uniqueLines === I.rows),
      checkHTML('Line revenue = price × qty', I.badQty ? int(I.badQty) + ' rows off' : 'no exceptions', I.badQty === 0),
      checkHTML('Fact keys resolve to dimensions', I.unresolved ? int(I.unresolved) + ' rows' : 'all rows', I.unresolved === 0),
      checkHTML('Lines shipped after due date', int(I.late), I.late === meta.lateLines)
    ].join('');

    const criteria = [
      ['G1', 'the workbook is unchanged', 'the extract is rebuilt with build/prepare_data.py', 'revenue equals $307,092,945.20 and gross profit equals $126,290,577.65, both computed as Σ(unit amount × OrderQuantity).'],
      ['G2', 'a period preset is chosen', 'it is applied', 'every KPI, chart and table on all five pages reflects only those lines and the Detail footer equals the KPI revenue.'],
      ['G3', 'a product line is selected', 'a territory bar is clicked', 'the filters combine with AND, the cross-filter chip is shown, and clearing it restores the previous totals exactly.'],
      ['G4', 'a filter state is active', 'Export view is used', 'the CSV contains exactly the matching order lines and its LineRevenue column sums to the on-screen revenue.'],
      ['G5', 'every LateDays value is zero', 'the Detail page is opened', 'Late line rate shows 0.00% and late lines shows 0 instead of a blank card.'],
      ['G6', 'a reviewer note was saved', 'the page is reloaded', 'the note and its UTC save time are restored from local storage.']
    ].map(function (c) {
      return '<p><b>' + c[0] + '</b> — <b>Given</b> ' + esc(c[1]) + ', <b>when</b> ' + esc(c[2]) + ', <b>then</b> ' + esc(c[3]) + '</p>';
    }).join('');

    return '<div class="card-kicker">Control totals · recomputed in the browser</div>' +
      '<div class="check-grid">' + checks + '</div>' +
      '<div class="notes-grid">' +
      '<div><h3>Assumptions</h3><ul>' +
      '<li>Reporting currency is taken as-is from the workbook; no exchange rates exist, so no conversion is applied.</li>' +
      '<li>Fact dates are the re-based 2021–2022 timeline that ships in the extract (2021 ≈ 2005+2006, 2022 ≈ 2007+2008). The unshifted YYYYMMDD keys map to 2005-07-01 → 2008-07-31.</li>' +
      '<li>Late means ship date after due date; where both fall on the same day the line is on time.</li>' +
      '<li>Income bands and lifetime value quartiles are derived at runtime from YearlyIncome and lifetime revenue.</li>' +
      '<li>Text columns are treated as null when they contain only a zero-length string.</li>' +
      '</ul></div>' +
      '<div><h3>Known limitations</h3><ul>' +
      '<li>No product subcategory or category sheet exists, so the 1–37 SubcategoryKey values cannot be labelled. Only 158 of 606 products ever sell.</li>' +
      '<li>PromotionKey and CurrencyKey have no dimension or rate table; they are unused.</li>' +
      '<li>No returns, refunds or budget data — this is shipped sales only.</li>' +
      '<li>Sales territory is read from the fact row; customer country is a separate segmentation. Combining both paths in one visual would create ambiguous filtering.</li>' +
      '<li>Review notes stay in this browser (local storage); there is no server-side persistence.</li>' +
      '</ul></div>' +
      '</div>' +
      '<div class="modal-section"><h3>Acceptance criteria</h3>' + criteria + '</div>' +
      '<div class="modal-section"><h3>Provenance</h3><p>Source: <b>' + esc(meta.source) + '</b> · extract generated <b>' + esc(meta.generatedUtc) + '</b> · ' +
      int(meta.rows) + ' fact rows, ' + int(meta.customers) + ' customers, ' + int(meta.products) + ' products (' + int(meta.soldProducts) + ' sold).</p></div>' +
      '<div class="card review">' +
      '<div class="toolbar-label">Reviewer note</div>' +
      '<textarea id="reviewText" placeholder="Record sign-off, open questions or a change request for this dashboard.">' + esc(state.review || '') + '</textarea>' +
      '<div class="review-actions"><button class="btn" type="button" data-action="save-review">Save note</button>' +
      '<span class="review-status" id="reviewStatus">' + (state.reviewUtc ? 'Saved ' + esc(state.reviewUtc) : 'Not saved yet') + '</span></div>' +
      '</div>';
  }

  function openNotes() {
    if (!els.modal || !els.modalBody) return;
    els.modalBody.innerHTML = notesHTML();
    els.modal.hidden = false;
    document.body.style.overflow = 'hidden';
  }

  function closeModal() {
    if (!els.modal) return;
    els.modal.hidden = true;
    document.body.style.overflow = '';
  }

  function loadReview() {
    try {
      const raw = localStorage.getItem(REVIEW_KEY);
      if (!raw) return;
      const rec = JSON.parse(raw);
      state.review = typeof rec.text === 'string' ? rec.text : '';
      state.reviewUtc = rec.utc || '';
    } catch (e) { /* storage unavailable */ }
  }

  function saveReview() {
    const ta = document.getElementById('reviewText');
    if (!ta) return;
    const rec = {
      text: ta.value,
      utc: new Date().toISOString().replace('T', ' ').slice(0, 16) + ' UTC'
    };
    state.review = rec.text;
    state.reviewUtc = rec.utc;
    try { localStorage.setItem(REVIEW_KEY, JSON.stringify(rec)); } catch (e) { /* storage unavailable */ }
    const st = document.getElementById('reviewStatus');
    if (st) { st.textContent = 'Saved ' + rec.utc; st.classList.add('saved'); }
    toast('Review note saved in this browser');
  }

  /* ---------------------------------------------------------------- export */

  function download(name, text) {
    const blob = new Blob(['\ufeff' + text], { type: 'text/csv;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = name;
    document.body.appendChild(a);
    a.click();
    setTimeout(function () { URL.revokeObjectURL(url); a.remove(); }, 900);
  }

  function exportCsv() {
    const R = currentRows();
    const head = ['OrderDate', 'OrderNumber', 'LineNumber', 'ProductKey', 'Product', 'ProductLine', 'CustomerKey', 'Customer',
      'CustomerCountry', 'TerritoryKey', 'Territory', 'TerritoryGroup', 'Quantity', 'UnitPrice', 'UnitCost',
      'LineRevenue', 'LineProfit', 'LineFreight', 'LeadDays', 'LateDays'];
    const out = [head.join(',')];
    for (let i = 0; i < R.length; i++) {
      const r = R[i];
      const p = products[r[1]];
      const c = customers[r[2]];
      const t = territories[r[3]];
      out.push([
        dates[r[0]], AW.orders[r[4]], r[13], p.k, p.n, PROD_LINE[r[1]], c.k, c.n, CUST_COUNTRY[r[2]],
        t.k, t.region, t.group, r[5], r[6].toFixed(4), r[7].toFixed(4),
        r[8].toFixed(4), r[9].toFixed(4), r[10].toFixed(4), r[11], r[12]
      ].map(csvCell).join(','));
    }
    const stamp = new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-');
    download('adventureworks-internet-sales-' + R.length + '-lines-' + stamp + '.csv', out.join('\r\n'));
    toast('Exported ' + int(R.length) + ' order lines');
  }

  /* ------------------------------------------------------------------ toast */

  const toastEl = document.createElement('div');
  toastEl.className = 'toast';
  toastEl.setAttribute('role', 'status');
  document.body.appendChild(toastEl);
  let toastTimer = null;
  function toast(msg) {
    toastEl.textContent = msg;
    toastEl.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { toastEl.classList.remove('show'); }, 2600);
  }

  /* ------------------------------------------------------------------- boot */

  function setText(id, value) {
    const el = document.getElementById(id);
    if (el) el.textContent = value;
  }

  function boot_() {
    setText('metaSource', meta.source);
    setText('metaPeriod', dates[0].slice(0, 4) + ' – ' + dates[dates.length - 1].slice(0, 4));
    setText('metaRows', int(meta.rows));
    setText('metaGenerated', meta.generatedUtc);
    if (els.footerMeta) {
      els.footerMeta.textContent = 'All monetary values in reporting currency · ' + int(meta.rows) +
        ' order lines · generated ' + meta.generatedUtc;
    }

    const allowed = ['overview', 'profitability', 'customers', 'geography', 'detail'];
    const hash = (location.hash || '').replace('#', '');
    if (allowed.indexOf(hash) !== -1) state.page = hash;

    loadReview();
    buildMenus();
    bindChrome();

    if (els.exportBtn) {
      els.exportBtn.addEventListener('click', function () { exportCsv(); });
    }
    if (els.notesBtn) {
      els.notesBtn.addEventListener('click', function () { openNotes(); });
    }
    if (els.modal) {
      els.modal.addEventListener('click', function (ev) {
        if (ev.target.closest('[data-close-modal]')) { closeModal(); return; }
        if (ev.target.closest('[data-action="save-review"]')) { saveReview(); }
      });
    }

    render();

    requestAnimationFrame(function () {
      boot.classList.add('hide');
      setTimeout(function () { if (boot.parentNode) boot.parentNode.removeChild(boot); }, 420);
    });
  }

  boot_();
})();
